pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        vm.assume(v >= 0);
        vm.assume(_decimals >= 0);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        bool ok;
        bool ret;
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool result) {
            ok = true;
            ret = result;
        } catch {
            ok = false;
        }
        assertTrue(!ok || ret == true);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);
        bool reverted; try c.transfer(from, caddress, _tos, v, _decimals) { reverted = false; } catch { reverted = true; }
        bool allSucceed = true;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        uint _value = v * 10 ** _decimals;
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], _value));
            if (!success) { allSucceed = false; break; }
        }
        assert(reverted == !allSucceed);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public payable {
        require(_tos.length > 0);
        bool reverted; try c.transfer(from, caddress, _tos, v, _decimals) { reverted = false; } catch { reverted = true; }
        assert(!reverted || _tos.length == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        require(true);
        bool reverted; try c.transfer(from, caddress, _tos, v, _decimals) { reverted = false; } catch { reverted = true; }
        bool anyFailure = false;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        uint _value = v * 10 ** _decimals;
        for (uint i = 0; i < _tos.length && !anyFailure; i++) {
            (bool s, ) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], _value));
            if (!s) anyFailure = true;
        }
        assert(!anyFailure || reverted);
    }
}

